theorem QuarticQuery.sf_uniform_parameters
    (k t L : ℕ) (hk : 2 ≤ k) (ht : 15 * k + 2 ≤ 2 * t)
    (hL : 1 ≤ L) (hLX : (L : ℝ) ≤ (Real.rpow (mValue t : ℝ) (1 - 1 / (k : ℝ)) / (2332800 * (k : ℝ)^2 * Real.log (4 * (k : ℝ) * (mValue t : ℝ))))) :
    let m : ℝ := mValue t
    let a : ℝ := (1 / 18) ^ (k - 1)
    let δ : ℝ := 1 / (2 : ℝ) ^ (5 * k)
    let ε : ℝ := (8 / 9) ^ (25 * k)
    let Λ : ℝ := 2 * (k : ℝ) * Real.log (4 * (k : ℝ) * m)
    let K : ℝ := Real.sqrt (8 * (50 * (k : ℝ) * (L : ℝ) + 1) * Λ)
    (119 / 144 : ℝ) * a ≤ (1 - ε) * (a - δ) - ε - 4 / (m * δ^2) ∧
    K^2 ≤ (1 + 1 / (50 * (k : ℝ))) * Real.rpow m (1 - 1 / (k : ℝ)) / 2916 ∧
    (3 / Real.sqrt m)^(k-1) * K^k ≤ a / 48 ∧
    (1 / 2 : ℝ)^k * (3 / Real.sqrt m)^(k-1) ≤ a / 4 ∧
    (2 * (k : ℝ) * m)^k * (4 * (k : ℝ) * m)^k * Real.exp (-Λ) = (1 / 2 : ℝ)^k

theorem QuarticQuery.sf_exact_exponent_5 (t : ℕ) (ht : 80 ≤ t) :
    let k := Nat.sqrt (t/10)
    let f := (totalise (Fkm (k - 1 + 1) t (forrCircuit (k - 1) t)))
    let s : ℝ := 2*(t : ℝ)
    let B : ℕ := (2972284080 * k * (1 + 122880256 * 2 ^ (5 * k)) + 79491312000 * (k + 1) ^ 2 + 1131887160)
    let A : ℝ := (2-1/(k : ℝ))*s -
      Real.logb 2 (466560000*(k : ℝ)^2*Real.log (4*(k : ℝ)*(mValue t : ℝ)))
    let D : ℝ := s/2 + Real.logb 2 (B : ℝ) + 6*Real.logb 2 s
    1 < Q f ∧ 0 < A/D ∧ A/D < Real.log (R f : ℝ) / Real.log (Q f : ℝ) ∧
      Real.rpow (Q f : ℝ) (A/D) < (R f : ℝ)

